<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --signature</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checksums.txt.sig</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
